      "@type": "FAQPage",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Doet een behandeling met spierontspanners pijn?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "De meeste patiënten omschrijven het als een kort, licht prikje. De naaldjes zijn zeer dun en er is geen verdoving nodig."
          }
        },
        {
          "@type": "Question",
          "name": "Krijg ik een \"bevroren\" gezicht?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Nee. Bij een correct gedoseerde behandeling blijft je mimiek volledig behouden — je kunt nog gewoon fronsen, lachen en verbaasd kijken. Enkel de rimpels die daarbij ontstaan worden zachter."
          }
        },
        {
          "@type": "Question",
          "name": "Hoelang blijft het resultaat zichtbaar?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Het effect bouwt zich op vanaf dag drie en is na twee weken volledig zichtbaar. Gemiddeld blijft het resultaat drie tot vier maanden aanhouden."
          }
        },
        {
          "@type": "Question",
          "name": "Wat kost het eerste consult?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Niets. Het eerste consult bij dr. Sasha Kenis is steeds gratis en volledig vrijblijvend."
          }
        }
